200	    /**
201	     * Builds the immutable structured {@code OWNER_CREATED} audit event emitted (in addition to the
202	     * human-readable audit line) on a successful create, as a JSON object
203	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. The {@code seq} is
204	     * a fresh value from the monotonically increasing {@link #AUDIT_EVENT_SEQ} sequence, so the event
205	     * stream is strictly ordered across creates.
206	     * <p>
207	     * The {@code customerCode} field carries the owner's current primary identifier (see
208	     * {@link #primaryIdentifier}); it is the {@code customerCode} today and becomes whatever replaces it
209	     * once the identifier is unified, so the event always names the owner by its live primary identifier.
210	     *
211	     * @param owner the just-saved owner
212	     * @param ownerDto the mapped DTO, used for the (possibly derived) {@code membershipLevel}
213	     * @return the JSON-encoded structured event
214	     */
215	    private String ownerCreatedEvent(Owner owner, OwnerDto ownerDto) {
216	        StringBuilder json = new StringBuilder(128);
217	        json.append('{');
218	        json.append("\"seq\":").append(AUDIT_EVENT_SEQ.incrementAndGet());
219	        json.append(",\"ownerId\":").append(owner.getId());
220	        json.append(",\"customerCode\":").append(jsonString(primaryIdentifier(owner)));
221	        json.append(",\"membershipLevel\":").append(ownerDto.getMembershipLevel());
222	        json.append(",\"event\":\"OWNER_CREATED\"");
223	        json.append('}');
224	        return json.toString();
225	    }
