227	    /**
228	     * The owner's current primary identifier carried by the structured audit event. Today this is the
229	     * assigned {@code customerCode}; when the identifier is later unified into the {@code memberId} this
230	     * is the sole place to switch, so the event begins carrying the {@code memberId} instead.
231	     *
232	     * @param owner the just-saved owner
233	     * @return the owner's live primary identifier
234	     */
235	    private String primaryIdentifier(Owner owner) {
236	        return owner.getCustomerCode();
237	    }
