239	    /**
240	     * Encodes a value as a JSON string literal (quoted, with the JSON-significant characters escaped),
241	     * or the literal {@code null} when the value is absent.
242	     */
243	    private static String jsonString(String value) {
244	        if (value == null) {
245	            return "null";
246	        }
247	        StringBuilder sb = new StringBuilder(value.length() + 2);
248	        sb.append('"');
249	        for (int i = 0; i < value.length(); i++) {
250	            char c = value.charAt(i);
251	            switch (c) {
252	                case '"' -> sb.append("\\\"");
253	                case '\\' -> sb.append("\\\\");
254	                case '\n' -> sb.append("\\n");
255	                case '\r' -> sb.append("\\r");
256	                case '\t' -> sb.append("\\t");
257	                default -> {
258	                    if (c < 0x20) {
259	                        sb.append(String.format("\\u%04x", (int) c));
260	                    } else {
261	                        sb.append(c);
262	                    }
263	                }
264	            }
265	        }
266	        sb.append('"');
267	        return sb.toString();
268	    }
