270	    /**
271	     * Reads the optional {@code Idempotency-Key} header from the current request, if any. A create
272	     * carrying this header is idempotent: the first create under a key is recorded, and a later create
273	     * with the same key returns the originally created owner instead of creating a duplicate.
274	     *
275	     * @return the trimmed idempotency key, or {@code null} when the header is absent, blank or there is
276	     *         no active servlet request
277	     */
278	    private String currentIdempotencyKey() {
279	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
280	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
281	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
282	            if (key != null && !key.isBlank()) {
283	                return key.trim();
284	            }
285	        }
286	        return null;
287	    }
