289	    /**
290	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
291	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
292	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
293	     * date, before any business-day adjustment.
294	     *
295	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
296	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
297	     */
298	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
299	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
300	            throw new FutureRegistrationDateException(registrationDate);
301	        }
302	    }
