304	    /**
305	     * The maximum number of owners that may be created in a single day. Creating an owner once this
306	     * many owners already carry today's {@code registrationDate} is rejected.
307	     */
308	    private static final int DAILY_OWNER_LIMIT = 100;
309	
310	    /**
311	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
312	     * given business day as their {@code registrationDate}. The count is keyed by the
313	     * business-day-adjusted registration date of the owner being created (see
314	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
315	     * with no {@code registrationDate} are ignored.
316	     *
317	     * @param registrationDate the business-day-adjusted registration date of the owner being created
318	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
319	     */
320	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
321	        long count = this.clinicService.findAllOwners().stream()
322	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
323	            .count();
324	        if (count >= DAILY_OWNER_LIMIT) {
325	            throw new DailyOwnerLimitException(registrationDate);
326	        }
327	    }
