329	    /**
330	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
331	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
332	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
333	     */
334	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
335	
336	    /**
337	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
338	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
339	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
340	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
341	     * owner being created is excluded (it has not yet been saved).
342	     *
343	     * @param registrationDate the business-day-adjusted registration date of the owner being created
344	     * @return {@code true} if more than the threshold of owners already carry this business day
345	     */
346	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
347	        long count = this.clinicService.findAllOwners().stream()
348	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
349	            .count();
350	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
351	    }
