353	    /**
354	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
355	     * these dates is rolled forward, just as it is for a weekend.
356	     */
357	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
358	        java.time.LocalDate.parse("2026-01-01"),
359	        java.time.LocalDate.parse("2026-01-26"),
360	        java.time.LocalDate.parse("2026-04-25"),
361	        java.time.LocalDate.parse("2026-12-25"),
362	        java.time.LocalDate.parse("2026-12-28"));
363	
364	    /**
365	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
366	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
367	     * unchanged. This applies to the effective registration date whether it was supplied in the
368	     * request or defaulted to the server date, and every value derived from the registration date
369	     * uses the adjusted result.
370	     *
371	     * @param date the effective registration date
372	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
373	     */
374	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
375	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
376	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
377	            || PUBLIC_HOLIDAYS.contains(date)) {
378	            date = date.plusDays(1);
379	        }
380	        return date;
381	    }
