389	    /**
390	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
391	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
392	     * treated as empty).
393	     *
394	     * @param city the city of the owner being created
395	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
396	     */
397	    private void rejectCityAtCapacity(String city) {
398	        String cityValue = city == null ? "" : city;
399	        long count = this.clinicService.findAllOwners().stream()
400	            .filter(existing -> cityValue.equalsIgnoreCase(
401	                existing.getCity() == null ? "" : existing.getCity()))
402	            .count();
403	        if (count >= CITY_CAPACITY) {
404	            throw new CityAtCapacityException(city);
405	        }
406	    }
