408	    /**
409	     * The number of owners a city must already hold for a new owner in it to raise a
410	     * {@code capacityWarning}. Once a city holds at least this many owners (but fewer than the hard
411	     * {@link #CITY_CAPACITY} limit) the next owner created in it warns that the city is approaching
412	     * capacity.
413	     */
414	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
415	
416	    /**
417	     * Computes the {@code capacityWarning} for an owner being created: {@code true} when the owner's
418	     * city already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
419	     * {@value #CITY_CAPACITY} minus one owners (approaching, but not yet at, the hard
420	     * {@link #CITY_CAPACITY} limit), otherwise {@code false}. Owners are counted per city the same way
421	     * the hard capacity rule counts them (see {@link #rejectCityAtCapacity}), comparing the city name
422	     * case-insensitively with a {@code null} city treated as empty, and the owner being created is
423	     * excluded (it has not yet been saved). A city already at or beyond the hard limit is rejected
424	     * before this runs, so it never reports a warning.
425	     *
426	     * @param city the city of the owner being created
427	     * @return {@code true} if the city is approaching its capacity limit
428	     */
429	    private boolean computeCapacityWarning(String city) {
430	        String cityValue = city == null ? "" : city;
431	        long count = this.clinicService.findAllOwners().stream()
432	            .filter(existing -> cityValue.equalsIgnoreCase(
433	                existing.getCity() == null ? "" : existing.getCity()))
434	            .count();
435	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
436	    }
