438	    /**
439	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
440	     * REGION is the owner's canonical region (derived by preferring the postcode, see
441	     * {@link Localities#region(String, String)} — the same region derivation shared with the
442	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
443	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
444	     * The code is derived from the owner's own identity fields; it carries no sequence number.
445	     * <p>
446	     * When the computed code collides with an existing owner's {@code customerCode}, it is
447	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
448	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
449	     *
450	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
451	     * @param telephone the owner's normalized (E.164) telephone
452	     * @param lastName the owner's last name
453	     * @return the assigned customer code, de-duplicated to be unique among existing owners
454	     */
455	    private String assignCustomerCode(String region, String telephone, String lastName) {
456	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
457	        String hash8 = sha256UpperHex(basis).substring(0, 8);
458	        String code = region + "-" + hash8;
459	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
460	            .map(Owner::getCustomerCode)
461	            .filter(java.util.Objects::nonNull)
462	            .collect(java.util.stream.Collectors.toSet());
463	        if (!existing.contains(code)) {
464	            return code;
465	        }
466	        for (int n = 2; ; n++) {
467	            String candidate = code + "-" + n;
468	            if (!existing.contains(candidate)) {
469	                return candidate;
470	            }
471	        }
472	    }
473	
474	    /**
475	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
476	     */
477	    private static String sha256UpperHex(String value) {
478	        try {
479	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
480	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
481	            StringBuilder sb = new StringBuilder(digest.length * 2);
482	            for (byte b : digest) {
483	                sb.append(String.format("%02X", b));
484	            }
485	            return sb.toString();
486	        }
487	        catch (java.security.NoSuchAlgorithmException e) {
488	            throw new IllegalStateException("SHA-256 not available", e);
489	        }
490	    }
