529	    /**
530	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
531	     * ceiling. The owner's natural level is first derived from their own fields (see
532	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
533	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
534	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
535	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
536	     * the natural level is returned.
537	     *
538	     * @param owner the owner being created, with its level-affecting fields already populated
539	     * @return the (possibly capped) membership level to store on the owner
540	     */
541	    private int cappedMembershipLevel(Owner owner) {
542	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
543	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
544	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
545	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
546	            .filter(this::isNotDeleted)
547	            .filter(existing -> householdId.equals(
548	                Households.householdId(existing.getLastName(), existing.getPostcode())))
549	            .mapToInt(this::effectiveMembershipLevel)
550	            .max();
551	        if (maxMemberLevel.isEmpty()) {
552	            return naturalLevel;
553	        }
554	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
555	    }
