557	    /**
558	     * Returns an existing owner's effective {@code membershipLevel}: the stored value when present (the
559	     * value assigned, and possibly capped, when that owner was created), otherwise the level derived
560	     * from its own fields for owners that predate the stored level (e.g. seed data).
561	     *
562	     * @param owner an existing owner
563	     * @return the owner's effective membership level
564	     */
565	    private int effectiveMembershipLevel(Owner owner) {
566	        if (owner.getMembershipLevel() != null) {
567	            return owner.getMembershipLevel();
568	        }
569	        return org.springframework.samples.petclinic.util.Memberships.membershipLevel(
570	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
571	    }
