573	    /**
574	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
575	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
576	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
577	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
578	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
579	     * identity key, two owners with the same last name and postcode but different telephones are a soft
580	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
581	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
582	     * soft-match.
583	     *
584	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
585	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
586	     */
587	    private Integer findPossibleDuplicateOf(Owner owner) {
588	        String postcode = owner.getPostcode();
589	        if (postcode == null) {
590	            return null;
591	        }
592	        String soundex = Households.soundex(owner.getLastName());
593	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
594	        return this.clinicService.findAllOwners().stream()
595	            .filter(this::isNotDeleted)
596	            .filter(existing -> soundex.equals(Households.soundex(existing.getLastName())))
597	            .filter(existing -> postcode.equals(existing.getPostcode()))
598	            .filter(existing -> !identity.equals(Households.identityKey(
599	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())))
600	            .map(Owner::getId)
601	            .filter(java.util.Objects::nonNull)
602	            .min(java.util.Comparator.naturalOrder())
603	            .orElse(null);
604	    }
605	
606	    /**
607	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
608	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
609	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
610	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
611	     * {@code "+61412345678"}. The E.164 value is stored and returned.
612	     * <p>
613	     * The national-number length (the digits after the country code) is additionally validated for
614	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
615	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
616	     *
617	     * @param telephone the raw telephone as submitted
618	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
619	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
620	     *         or its national-number length is wrong for its country code
621	     */
622	    private String normalizeTelephone(String telephone) {
623	        String raw = telephone == null ? "" : telephone.trim();
624	        boolean hasCountryCode = raw.startsWith("+");
625	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
626	        if (hasCountryCode) {
627	            cleaned = cleaned.substring(1);
628	        }
629	        String digits;
630	        if (hasCountryCode) {
631	            digits = cleaned;
632	        } else {
633	            if (cleaned.startsWith("0")) {
634	                cleaned = cleaned.substring(1);
635	            }
636	            digits = "61" + cleaned;
637	        }
638	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
639	            throw new InvalidTelephoneException(telephone);
640	        }
641	        return "+" + digits;
642	    }
643	
644	    /**
645	     * Checks the national-number length of an E.164 digit string against its country code for the
646	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
647	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
648	     *
649	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
650	     * @return {@code true} if the national-number length is acceptable for the country code
651	     */
652	    private boolean hasValidNationalLength(String digits) {
653	        if (digits.startsWith("61")) {
654	            return digits.length() - 2 == 9;
655	        }
656	        if (digits.startsWith("1")) {
657	            return digits.length() - 1 == 10;
658	        }
659	        return true;
660	    }
661	
662	    /**
663	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
664	     * multi-character top-level label. Deliberately lenient about the exact character set while still
665	     * rejecting values that are clearly not addresses (e.g. missing '@').
666	     */
667	    private static final java.util.regex.Pattern EMAIL_PATTERN =
668	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
669	
670	    /**
671	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
672	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
673	     * lower-cased email domain.
674	     */
675	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
676	        "mailinator.com", "tempmail.com", "guerrillamail.com");
677	
678	    /**
679	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
680	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
681	     * lower-cased before being stored and returned.
682	     *
683	     * @param email the raw email as submitted, may be {@code null}
684	     * @return the lower-cased email, or {@code null} when none was supplied
685	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
686	     */
687	    private String normalizeEmail(String email) {
688	        if (email == null || email.isBlank()) {
689	            return null;
690	        }
691	        String trimmed = email.trim();
692	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
693	            throw new InvalidEmailException(email);
694	        }
695	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
696	        String domain = normalized.substring(normalized.indexOf('@') + 1);
697	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
698	            throw new DisposableEmailException(email);
699	        }
700	        return normalized;
701	    }
702	
703	    /**
704	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
705	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
706	     * {@link Localities#region}) accepts any 4-digit postcode.
707	     */
708	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
709	        "NSW", new int[] {2000, 2099},
710	        "VIC", new int[] {3000, 3099},
711	        "QLD", new int[] {4000, 4099});
712	
713	    /**
714	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
715	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
716	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
717	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
718	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
719	     *
720	     * @param city the owner's city, used to derive the region whose range constrains the postcode
721	     * @param postcode the raw postcode as submitted, may be {@code null}
722	     * @return the postcode when supplied, or {@code null} when none was supplied
723	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
724	     *         out of range for the city's region
725	     */
726	    private String validatePostcode(String city, String postcode) {
727	        if (postcode == null || postcode.isBlank()) {
728	            return null;
729	        }
730	        if (!postcode.matches("[0-9]{4}")) {
731	            throw new InvalidPostcodeException(postcode);
732	        }
733	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
734	        if (range != null) {
735	            int value = Integer.parseInt(postcode);
736	            if (value < range[0] || value > range[1]) {
737	                throw new InvalidPostcodeException(postcode);
738	            }
739	        }
740	        return postcode;
741	    }
742	
743	    /**
744	     * Common street-type abbreviations expanded to their full word during address normalization.
745	     */
746	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
747	        "ST", "STREET",
748	        "RD", "ROAD",
749	        "AVE", "AVENUE");
750	
751	    /**
752	     * Applies the owner's address on create from the structured fields when present, falling back to the
753	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
754	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
755	     * {@code address}; when neither is present the create is rejected.
756	     * <p>
757	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
758	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
759	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
760	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
761	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
762	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
763	     *
764	     * @param owner the owner being created
765	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
766	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
767	     */
768	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
769	        String rawLine1 = ownerFieldsDto.getAddressLine1();
770	        String rawLine2 = ownerFieldsDto.getAddressLine2();
771	        String rawFlat = ownerFieldsDto.getAddress();
772	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
773	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
774	        if (!hasLine1 && !hasFlat) {
775	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
776	        }
777	        if (hasLine1) {
778	            String line1 = normalizeAddress(rawLine1);
779	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
780	            owner.setAddressLine1(line1);
781	            owner.setAddressLine2(line2);
782	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
783	        } else {
784	            owner.setAddressLine1(null);
785	            owner.setAddressLine2(null);
786	            owner.setAddress(normalizeAddress(rawFlat));
787	        }
788	    }
789	
790	    /**
791	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
792	     * whitespace collapse to a single space, the value is upper-cased and common street-type
793	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
794	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
795	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
796	     * for every address comparison (household duplicate detection and the shared household id).
797	     *
798	     * @param address the raw address as submitted
799	     * @return the normalized address
800	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
801	     */
802	    private String normalizeAddress(String address) {
803	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
804	        if (collapsed.isEmpty()) {
805	            throw new InvalidAddressException(address);
806	        }
807	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
808	        StringBuilder normalized = new StringBuilder(collapsed.length());
809	        for (int i = 0; i < tokens.length; i++) {
810	            if (i > 0) {
811	                normalized.append(' ');
812	            }
813	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
814	        }
815	        return normalized.toString();
816	    }
817	
818	    /**
819	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
820	     * is consolidated onto the single derived {@code identityKey} (see
821	     * {@link Households#identityKey(String, String, String)}): the SHA-256 hex over the normalized
822	     * telephone, the lower-cased email (a {@code null} email compared as an empty segment) and the
823	     * {@code soundex} of the last name. Two owners are duplicates when their identity keys are equal.
824	     * Existing telephones are re-normalized to E.164 before comparison, so equivalent values submitted
825	     * in different formats (e.g. national {@code "0412 345 678"} and international
826	     * {@code "+61 412 345 678"}) still match. The email-domain blocklist is applied first (during
827	     * email normalization), and soft-deleted owners are ignored.
828	     * <p>
829	     * Because the telephone is part of the key, two members of one household (same last name and
830	     * postcode) with different telephones have different identity keys and are both allowed; such a
831	     * near-match is instead surfaced as a soft duplicate (see {@link #findPossibleDuplicateOf}).
832	     *
833	     * @param owner the owner being created, with its telephone and email already normalized
834	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity key
835	     */
836	    private void rejectDuplicateIdentity(Owner owner) {
837	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
838	        boolean duplicate = this.clinicService.findAllOwners().stream()
839	            .filter(this::isNotDeleted)
840	            .anyMatch(existing -> identity.equals(Households.identityKey(
841	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())));
842	        if (duplicate) {
843	            throw new DuplicateIdentityException(identity);
844	        }
845	    }
846	
847	    /**
848	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
849	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
850	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
851	     */
852	    private boolean isNotDeleted(Owner owner) {
853	        return !Boolean.TRUE.equals(owner.getDeleted());
854	    }
855	
856	    /**
857	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
858	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
859	     * when its national-number length does not match its country code.
860	     */
861	    private String toE164OrNull(String telephone) {
862	        try {
863	            return normalizeTelephone(telephone);
864	        } catch (InvalidTelephoneException e) {
865	            return null;
866	        }
867	    }
868	
869	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
870	    @Override
871	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
872	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
873	        if (currentOwner == null) {
874	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
875	        }
876	        currentOwner.setAddress(ownerFieldsDto.getAddress());
877	        currentOwner.setCity(ownerFieldsDto.getCity());
878	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
879	        currentOwner.setLastName(ownerFieldsDto.getLastName());
880	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
881	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
882	        this.clinicService.saveOwner(currentOwner);
883	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
884	    }
885	
886	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
887	    @Transactional
888	    @Override
889	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
890	        Owner owner = this.clinicService.findOwnerById(ownerId);
891	        if (owner == null) {
892	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
893	        }
894	        this.clinicService.deleteOwner(owner);
895	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
896	    }
897	
898	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
899	    @Override
900	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
901	        Owner owner = this.clinicService.findOwnerById(ownerId);
902	        if (owner == null) {
903	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
904	        }
905	        HttpHeaders headers = new HttpHeaders();
906	        Pet pet = petMapper.toPet(petFieldsDto);
907	        owner.setId(ownerId);
908	        pet.setOwner(owner);
909	        pet.getType().setName(null);
910	        this.clinicService.savePet(pet);
911	        PetDto petDto = petMapper.toPetDto(pet);
912	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
913	            .buildAndExpand(pet.getId()).toUri());
914	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
915	    }
916	
917	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
918	    @Override
919	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
920	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
921	        if (currentOwner != null) {
922	            Pet currentPet = this.clinicService.findPetById(petId);
923	            if (currentPet != null) {
924	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
925	                currentPet.setName(petFieldsDto.getName());
926	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
927	                this.clinicService.savePet(currentPet);
928	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
929	            }
930	        }
931	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
932	    }
933	
934	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
935	    @Override
936	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
937	        HttpHeaders headers = new HttpHeaders();
938	        Visit visit = visitMapper.toVisit(visitFieldsDto);
939	        Pet pet = new Pet();
940	        pet.setId(petId);
941	        visit.setPet(pet);
942	        this.clinicService.saveVisit(visit);
943	        VisitDto visitDto = visitMapper.toVisitDto(visit);
944	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
945	            .buildAndExpand(visit.getId()).toUri());
946	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
947	    }
948	
949	
950	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
951	    @Override
952	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
953	        Owner owner = this.clinicService.findOwnerById(ownerId);
954	        if (owner != null) {
955	            Pet pet = owner.getPet(petId);
956	            if (pet != null) {
957	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
958	            }
959	        }
960	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
961	    }
962	}
